entries[40769] = { ["name"] = "Scrapbot Construction Kit", ["text"] = "Use: Creates a mechanical Scrapbot that repairs equipment and buys nearly anything. The scrapbot leaves after 5 min. (15 Min Cooldown)\nRequires Northrend Engineering (50)\nSell Price:" }
entries[40771] = { ["name"] = "Cobalt Frag Bomb", ["text"] = "Use: Inflicts ( 29 * 10) to ( 37 * 10) Fire damage and incapacitates targets for 3 sec in a 3 yard radius. Any damage will break the effect.\n\nThe frag bomb has no effect on creatures above level 49. (1 Min Cooldown)\nRequires Northrend Engineering (1)\nSell Price:" }
entries[40772] = { ["name"] = "Gnomish Army Knife", ["text"] = "Use: An engineer with at least 1 skill in Northrend Engineering can overload the knife's battery and attempt to shock a dead ally back to life. Cannot be used in combat. (30 Min Cooldown)\n+10 Northrend Mining Skill.\n+10 Northrend Herbalism Skill.\n+10 Northrend Skinning Skill.\n\"Includes Gyromatic Micro-Adjustor, Arclight Spanner, Jeweler's Toolset, Blacksmithing Hammer, Back Scratcher, and Whirly Thing.\"\nSell Price:" }
